<script setup lang="ts">
import type {ReviewPolicy,ActionPolicy,FindingLabelPolicy} from '@/api/pipelines';
import {always,blankCondition,conditionCount} from '@/api/action-policy-editor';
import {labelBindingAddress} from '@/api/finding-label-policy';
import ActionConditionEditor from './ActionConditionEditor.vue';
const props=defineProps<{modelValue?:ReviewPolicy|null;actions?:ActionPolicy|null;findingCodes:string[];itemCodes:string[];labels?:FindingLabelPolicy|null;disabled?:boolean}>();
const emit=defineEmits<{'update:modelValue':[value:ReviewPolicy|undefined];'update:actions':[value:ActionPolicy|undefined]}>();
function toggle(enabled:boolean){if(props.disabled)return;if(enabled){emit('update:modelValue',{schemaVersion:'iqc-review-policy-v2',seed:'review-v1',unknownHandling:'REQUIRE_REVIEW',rules:[]});route();}else{emit('update:modelValue',undefined);const policy=props.actions;if(policy)emit('update:actions',{...policy,actions:policy.actions.filter(action=>!(action.actionId==='review_policy'&&action.type==='CREATE_REVIEW'&&action.condition.kind==='REVIEW_REQUIRED'&&action.condition.value===true&&action.configuration.reason==='复核政策要求'))});}}
function route(){if(props.disabled)return;const actions=props.actions?.actions||[];if(actions.some(action=>action.type==='CREATE_REVIEW'&&action.condition.kind==='REVIEW_REQUIRED'&&action.condition.value===true))return;if(actions.length>=100||actions.some(action=>action.actionId==='review_policy'))return;emit('update:actions',{schemaVersion:'iqc-action-policy-v1',actions:[...actions,{actionId:'review_policy',adapterVersion:1,type:'CREATE_REVIEW',condition:{kind:'REVIEW_REQUIRED',code:null,value:true,children:[]},idempotency:'PRODUCTION_SOURCE_V1',retry:null,failureHandling:'RECORD_ONLY',configuration:{reason:'复核政策要求'}}]});}
function update(patch:Partial<ReviewPolicy>){if(!props.disabled&&props.modelValue)emit('update:modelValue',{...props.modelValue,...patch});}
function rule(index:number,patch:Partial<ReviewPolicy['rules'][number]>){update({rules:props.modelValue!.rules.map((value,i)=>i===index?{...value,...patch}:value)});}
function add(preset:'CUSTOM'|'RISK'|'LOW'|'MID'|'NORMAL'){if(!props.modelValue||props.modelValue.rules.length>=100)return;let i=1;while(props.modelValue.rules.some(value=>value.ruleId===`review_${i}`))i++;update({rules:[...props.modelValue.rules,{ruleId:`review_${i}`,condition:preset==='RISK'?{kind:'RISK_AT_LEAST',code:null,value:'HIGH',children:[]}:preset==='CUSTOM'?blankCondition():always(),confidence:preset==='LOW'||preset==='MID'?{findingCode:'',minimumInclusive:preset==='MID'?'0.7':null,maximumExclusive:preset==='MID'?'0.9':'0.7'}:null,probability:preset==='MID'?'0.2':preset==='NORMAL'?'0.02':'1',fallback:preset==='NORMAL'}]});}
function confidence(index:number,patch:Partial<NonNullable<ReviewPolicy['rules'][number]['confidence']>>){const value=props.modelValue!.rules[index].confidence;if(value)rule(index,{confidence:{...value,...patch}});}
</script>
<template><section><h3>复核政策</h3><a-switch :checked="!!modelValue" :disabled="disabled" @change="(value:unknown)=>toggle(Boolean(value))"/><p>稳定抽样由冻结输入与种子决定，重复执行不会重新抽奖。复核创建使用下方CREATE_REVIEW动作及现有动作开关、授权和失败记录。</p><template v-if="modelValue"><p>{{modelValue.schemaVersion==='iqc-review-policy-v2'?'使用完整冻结输入的精确抽样身份':'保留已有V1抽样身份与桶'}}</p><template v-if="modelValue.schemaVersion==='iqc-review-policy-v1'"><a-button :disabled="disabled" @click="update({schemaVersion:'iqc-review-policy-v2'})">升级精确抽样身份，保留规则</a-button><p>升级后的新政策会重新确定抽样桶，已保存的旧版本保持原解释。</p></template>
<a-form-item label="抽样种子"><a-input :value="modelValue.seed" :disabled="disabled" :maxlength="128" @update:value="(value:string)=>update({seed:value})"/></a-form-item><a-form-item label="选中规则条件未知时"><a-select :value="modelValue.unknownHandling" :disabled="disabled" :options="[{value:'REQUIRE_REVIEW',label:'要求复核，保留事实未知'},{value:'KEEP_UNKNOWN',label:'保留复核决定未知'}]" @change="(value:ReviewPolicy['unknownHandling'])=>update({unknownHandling:value})"/></a-form-item>
<a-space wrap><a-button :disabled="disabled" @click="add('RISK')">高风险必审</a-button><a-button :disabled="disabled" @click="add('LOW')">低置信度必审</a-button><a-button :disabled="disabled" @click="add('MID')">中间置信度20%抽样</a-button><a-button :disabled="disabled" @click="add('NORMAL')">普通2%抽样</a-button><a-button :disabled="disabled" @click="add('CUSTOM')">自定义规则</a-button><a-button :disabled="disabled" @click="route">连接复核创建动作</a-button></a-space><p>置信度区间只读取已校准融合的真实选中事实；缺少校准数据按未知策略处理。概率抽样不保证有限批次恰好达到该比例。</p>
<a-card v-for="(value,index) in modelValue.rules" :key="index" size="small" style="margin:12px 0"><a-form-item label="规则编码 / 抽样概率0到1"><a-space><a-input :value="value.ruleId" :disabled="disabled" @update:value="(text:string)=>rule(index,{ruleId:text})"/><a-input :value="value.probability" :disabled="disabled" :maxlength="64" @update:value="(text:string)=>rule(index,{probability:text})"/></a-space></a-form-item><ActionConditionEditor :model-value="value.condition" :finding-codes="findingCodes" :item-codes="itemCodes" :label-codes="labels?.bindings.map(labelBindingAddress)||[]" :allow-context-conditions="true" :excluded-kinds="['REVIEW_REQUIRED']" :node-count="conditionCount(value.condition)" :disabled="disabled" @update:model-value="condition=>rule(index,{condition})"/>
<a-form-item label="普通结果兜底抽样"><a-switch :checked="value.fallback===true" :disabled="disabled" @change="(enabled:unknown)=>rule(index,{fallback:Boolean(enabled)})"/><p>特殊规则条件可能或确定成立时，普通兜底不再叠加抽样；最多一条兜底规则。</p></a-form-item><a-form-item label="附加校准置信度区间"><a-switch :checked="!!value.confidence" :disabled="disabled" @change="(enabled:unknown)=>rule(index,{confidence:enabled?{findingCode:'',minimumInclusive:null,maximumExclusive:null}:null})"/></a-form-item><template v-if="value.confidence"><a-select :value="value.confidence.findingCode||undefined" :options="findingCodes.map(code=>({value:code,label:code}))" :disabled="disabled" placeholder="选择置信度Finding" @change="(code:string)=>confidence(index,{findingCode:code})"/><a-space><a-input :value="value.confidence.minimumInclusive||''" :disabled="disabled" placeholder="包含下界，可空" @update:value="(text:string)=>confidence(index,{minimumInclusive:text||null})"/><a-input :value="value.confidence.maximumExclusive||''" :disabled="disabled" placeholder="不包含上界，可空" @update:value="(text:string)=>confidence(index,{maximumExclusive:text||null})"/></a-space></template><a-button danger :disabled="disabled" @click="update({rules:modelValue.rules.filter((_,i)=>i!==index)})">删除规则</a-button></a-card>
</template></section></template>
